def repeatedFramePrefix (b : Basis I 𝕜 E) (m r : ℕ) (s : Finset I) : E →L[𝕜] E :=
  (r / m : ℝ) • ContinuousLinearMap.id 𝕜 E +
    (1 / m : ℝ) • ∑ i ∈ s, basisRankOne b i

