lemma repeatedFramePrefix_norm_le (b : Basis I 𝕜 E) {m r : ℕ}
    (hm : 0 < m) (hr : r ≤ m) (hbound : basisFrameBound b ≤ m) (s : Finset I) (x : E) :
    ‖repeatedFramePrefix b m r s x‖ ≤ 2 * ‖x‖
